import 'dart:async';

void main() {
  runApp(StaticApp());
}

class StaticApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: "Halala",
      home: HomeScreen(),
    );
  }
}

class HomeScreen extends StatefulWidget {
  @override
  _HomeScreenState createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  Future<void> getPractices(int id) async {
    try {
      final res = await http.get(Uri.parse('https://peerlessoutdoor.herokuapp.com/api/practices/$id'));
      if (res.statusCode == 200) {
        setState(() {
          practices = res.body;
        });
      }
    } catch (e) {
      print(e);
    }
  }

  List<dynamic> practices = [];

  @override
  void initState() {
    super.initState();
    getPractices(1);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Sanctuary")),
      body: SafeArea(
        child: Column(
          children: [
            Expanded(
              child: ListView.builder(
                itemCount: practices.length,
                itemBuilder: (context, index) {
                  final practice = practices[index];
                  return ListTile(
                    onTap: () {},
                    title: Text(practice.title),
                    subtitle: Text(practice.description),
                  );
                },
              ),
            )
          ],
        ),
      ),
    );
  }
}
